use bench_sandbox::order::Order;
use bench_sandbox::invoice::line_total;
#[test] fn quantity_field_and_consumer_intact() {
    let o = Order::new("abc", 3);
    assert_eq!(o.quantity, 3);            // new name required
    assert_eq!(line_total(&o, 10), 30);  // consumer must still work
}
